#!/usr/bin/env bash
# Two fixes bundled together, both in service_files/windows/opslab_agent_service.py
# + agent/:
#
# 1. Remote start/stop/restart command channel (agent/commands.py +
#    ApiClient.get_pending_command/ack_command + a command-poll thread in
#    agent/main.py) - the Admin Panel's /api/v1/instances/commands endpoint
#    and the Start/Stop/Restart buttons already existed, nothing on the
#    Agent side ever polled for them.
#
# 2. THE ACTUAL CAUSE of "registration not confirmed after 15s" on the
#    Windows install just run: the Windows Service Manager launches
#    opslab_agent_service.py with sys.path[0] set to its own directory
#    (...\OpsLabAgent\service\), not the parent install dir where agent\
#    lives as a sibling folder - so `from agent.main import run` throws
#    ModuleNotFoundError and the service dies immediately after start,
#    before it ever gets a chance to register. Fixed by inserting the
#    parent install directory into sys.path before that import. (This is
#    the same bug an earlier fix_agent_tarball_servicebug.sh on this
#    server already found and fixed once - the backup zip this round of
#    changes was based on predated that fix, so it silently reverted it.)
#
# Updates BOTH this repo's own ./agent + ./service_files (what
# build_msi_selfcontained.sh / build_msi.sh / the exe builder stage from
# directly) AND the served app/static/installers/opslab-agent.tar.gz (what
# install.ps1 downloads for a fresh enrollment).
#
# Run from inside /root/admin_panel (or wherever this repo lives on the VPS).
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> [1/3] Extracting fixed agent/ + service_files/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'B64_EOF_MARKER'

B64_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if [ ! -f "$TMP_EXTRACT/agent/commands.py" ] || ! grep -q "_INSTALL_ROOT" "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py"; then
    echo "    ERROR: fix not found in the extracted payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
cp -f "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py" service_files/windows/opslab_agent_service.py
echo "    Updated agent/*.py and service_files/windows/opslab_agent_service.py in this repo."

echo "==> [2/3] Rewriting app/static/installers/opslab-agent.tar.gz"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> [3/3] Verifying the served tarball"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
VERIFY_DIR="$(mktemp -d)"
tar -xzf app/static/installers/opslab-agent.tar.gz -C "$VERIFY_DIR"
if [ -f "$VERIFY_DIR/agent/commands.py" ] && grep -q "_INSTALL_ROOT" "$VERIFY_DIR/service_files/windows/opslab_agent_service.py"; then
    echo "    Confirmed: both fixes are present in the packaged tarball."
else
    echo "    ERROR: fix not found in the packaged tarball!"
    rm -rf "$VERIFY_DIR"
    exit 1
fi
rm -rf "$VERIFY_DIR"

echo ""
echo "Done. Restart the app the same way as before:"
echo "    pkill -f 'admin_panel/run.py'"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > /root/admin_panel/app.log 2>&1 &"
echo ""
echo "On the Windows machine that already failed to register, re-run the enrollment"
echo "command as-is (it detects and stops the existing broken service before"
echo "reinstalling, per install.ps1's own pre-flight check):"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <token> -AdminUrl https://kiosksys.opslabsystems.cloud"
